package fun.p3nd.wolfox;
import android.app.*;import android.os.*;import android.content.*;import android.location.*;import android.provider.Settings;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;
public class MainActivity extends Activity {
 android.content.SharedPreferences pref;EditText code,lat,lon;TextView status;LinearLayout root;LocationManager lm;
 void msg(String s){runOnUiThread(()->{status.setText(s);Toast.makeText(this,s,Toast.LENGTH_LONG).show();});}
 Button btn(String s,Runnable r){Button b=new Button(this);b.setText(s);root.addView(b);b.setOnClickListener(v->r.run());return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);pref=getSharedPreferences("wolfox",0);lm=(LocationManager)getSystemService(LOCATION_SERVICE);
 ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setPadding(24,30,24,24);root.setOrientation(1);sc.addView(root);setContentView(sc);
 TextView title=new TextView(this);title.setText("WolFox GPS — نسخة اختبار Android 16");title.setTextSize(22);root.addView(title);
 status=new TextView(this);status.setText(pref.getBoolean("active",false)?"تم التفعيل محليًا":"التفعيل مطلوب");root.addView(status);
 code=new EditText(this);code.setHint("رمز التفعيل");root.addView(code);
 btn("تحقق من التفعيل",()->activate());
 lat=new EditText(this);lat.setHint("Latitude");lat.setInputType(8194);lat.setText(pref.getString("lat","21.5433"));root.addView(lat);
 lon=new EditText(this);lon.setHint("Longitude");lon.setInputType(8194);lon.setText(pref.getString("lon","39.1728"));root.addView(lon);
 btn("حفظ الموقع",()->{try{double a=Double.parseDouble(lat.getText().toString()),b=Double.parseDouble(lon.getText().toString());if(a< -90||a>90||b< -180||b>180)throw new Exception();pref.edit().putString("lat",String.valueOf(a)).putString("lon",String.valueOf(b)).apply();msg("تم حفظ الإحداثيات");}catch(Exception e){msg("إحداثيات غير صحيحة");}});
 btn("إضافة للمفضلة",()->{try{JSONArray a=new JSONArray(pref.getString("favorites","[]"));a.put(new JSONObject().put("lat",lat.getText().toString()).put("lon",lon.getText().toString()));pref.edit().putString("favorites",a.toString()).apply();msg("تم الحفظ في المفضلة");}catch(Exception e){msg("تعذر الحفظ");}});
 btn("عرض المفضلة",()->{try{JSONArray a=new JSONArray(pref.getString("favorites","[]"));String[] names=new String[a.length()];for(int i=0;i<a.length();i++)names[i]=a.getJSONObject(i).optString("lat")+", "+a.getJSONObject(i).optString("lon");new AlertDialog.Builder(this).setTitle("المفضلة").setItems(names,(d,i)->{try{JSONObject x=a.getJSONObject(i);lat.setText(x.optString("lat"));lon.setText(x.optString("lon"));}catch(Exception ignored){}}).setNegativeButton("إغلاق",null).show();}catch(Exception e){msg("تعذر عرض المفضلة");}});
 btn("فتح الخريطة",()->{try{String u="https://www.openstreetmap.org/?mlat="+lat.getText()+"&mlon="+lon.getText()+"#map=15/"+lat.getText()+"/"+lon.getText();startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(u)));}catch(Exception e){msg("تعذر فتح الخريطة");}});
 btn("تشغيل الموقع الوهمي",()->mock(true));btn("إيقاف الموقع الوهمي",()->mock(false));
 btn("إظهار الأيقونة العائمة",()->{if(Settings.canDrawOverlays(this)){try{startService(new Intent(this,FloatingService.class));msg("جارٍ إظهار الأيقونة العائمة");}catch(Exception e){msg("فشل تشغيل الأيقونة: "+e.getMessage());}}else{msg("فعّل إذن الظهور فوق التطبيقات ثم ارجع واضغط إظهار الأيقونة");startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,android.net.Uri.parse("package:"+getPackageName())));}});
 btn("إخفاء الأيقونة",()->stopService(new Intent(this,FloatingService.class)));
 }
 void activate(){String c=code.getText().toString().trim();if(c.isEmpty()){msg("أدخل رمز التفعيل");return;}new Thread(()->{try{HttpURLConnection h=(HttpURLConnection)new URL("https://gps.p3nd.fun/api/v2/android/activate.php").openConnection();h.setRequestMethod("POST");h.setConnectTimeout(8000);h.setReadTimeout(8000);h.setDoOutput(true);h.setRequestProperty("Content-Type","application/json");byte[] data=new JSONObject().put("code",c).put("package_name",getPackageName()).toString().getBytes("UTF-8");try(OutputStream out=h.getOutputStream()){out.write(data);}if(h.getResponseCode()!=200)throw new IOException("HTTP "+h.getResponseCode());ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=h.getInputStream()){byte[] buf=new byte[2048];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}JSONObject j=new JSONObject(out.toString("UTF-8"));if(j.optBoolean("success")){pref.edit().putBoolean("active",true).apply();msg("تم التفعيل");}else msg(j.optString("message","لم يتم قبول الرمز"));h.disconnect();}catch(Exception e){msg("تعذر التحقق من الخادم: "+e.getMessage());}}).start();}
 void mock(boolean on){if(!pref.getBoolean("active",false)){msg("التفعيل مطلوب");return;}try{if(on){try{lm.addTestProvider(LocationManager.GPS_PROVIDER,false,false,false,false,true,true,true,1,1);}catch(IllegalArgumentException ignored){}lm.setTestProviderEnabled(LocationManager.GPS_PROVIDER,true);Location l=new Location(LocationManager.GPS_PROVIDER);l.setLatitude(Double.parseDouble(lat.getText().toString()));l.setLongitude(Double.parseDouble(lon.getText().toString()));l.setAccuracy(5f);l.setTime(System.currentTimeMillis());l.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());lm.setTestProviderLocation(LocationManager.GPS_PROVIDER,l);}else lm.removeTestProvider(LocationManager.GPS_PROVIDER);msg(on?"الموقع التجريبي يعمل":"تم إيقاف الموقع التجريبي");}catch(Exception e){msg("اختر WolFox في خيارات المطور كتطبيق موقع وهمي: "+e.getMessage());}}
}